// Auto-generated design-rationale document. Pure assembly over the data model + the
// deterministic engine — no generation, no guessing. The authored `why`/limit notes ARE the
// documentation; this just collates them with the lint/power/BOM facts into a clean writeup.
import { designContext } from "./context.js";
import type { Block, Design, Range, Severity } from "./types.js";

const r1 = (n: number) => Math.round(n * 10) / 10;
const SEV: Record<Severity, string> = { error: "✕", warn: "▲", recommendation: "💡", info: "ℹ", unknown: "○" };
const fmt = (v: unknown): string => {
  if (v == null) return "";
  if (typeof v === "number" || typeof v === "string") return String(v);
  const x = v as Range, u = x.unit ? ` ${x.unit}` : "";
  if (x.value != null) return `${x.value}${u}`;
  if (x.min != null || x.max != null) return `${x.min ?? "?"}–${x.max ?? "?"}${u}`;
  return "";
};

/** A Markdown design report for `design`, collating authored intent with deterministic facts. */
export function designReport(design: Design, blocks: Map<string, Block>): string {
  const ctx = designContext(design, blocks);
  const errs = ctx.checks.filter((c) => c.severity === "error").length;
  const warns = ctx.checks.filter((c) => c.severity === "warn").length;
  const L: string[] = [];

  L.push(`# ${design.name}`, "");
  L.push(`*Auto-generated design report — ${ctx.instances.length} blocks, ${ctx.connections.length} connections, ${errs} errors / ${warns} warnings.*`, "");

  L.push("## Blocks", "");
  for (const inst of ctx.instances) {
    const b = blocks.get(inst.block);
    L.push(`### ${inst.ref} — ${b?.name ?? inst.block}`, "");
    L.push(inst.summary, "");
    if (b?.spec && Object.keys(b.spec).length) L.push("**Spec:** " + Object.entries(b.spec).map(([k, v]) => `${k} ${fmt(v)}`).join(" · "), "");
    if (b?.schematic?.parts?.length) {
      L.push("**Parts:**");
      for (const p of b.schematic.parts) L.push(`- \`${p.ref}\` ${p.value ?? p.part ?? p.type}${p.why ? ` — ${p.why}` : ""}`);
      L.push("");
    }
    if (b?.limits?.length) {
      L.push("**Limits:**");
      for (const lim of b.limits) L.push(`- ⚠ ${lim.field} = ${lim.value}${lim.unit ?? ""} — ${lim.note}`);
      L.push("");
    }
  }

  L.push("## Connections", "");
  if (!ctx.connections.length) L.push("- *(none)*");
  for (const c of ctx.connections) L.push(`- ${c.from} → ${c.to}${c.net ? ` (${c.net})` : ""}${c.type ? ` · ${c.type}` : ""}`);

  L.push("", "## Checks", "");
  if (!ctx.checks.length) L.push("- ✅ All clear.");
  for (const f of ctx.checks) L.push(`- ${SEV[f.severity] ?? "•"} **${f.rule}** — ${f.message}${f.derivation ? ` *(${f.derivation})*` : ""}`);

  L.push("", "## Power rails", "");
  if (!ctx.rails.length) L.push("- *(no rails)*");
  for (const rb of ctx.rails) L.push(`- **${rb.net}** (${rb.type}): ${r1(rb.drawA)}${rb.capacityA != null ? ` / ${rb.capacityA}` : ""} A${rb.usedPct != null ? ` — ${Math.round(rb.usedPct)}%` : ""}`);

  L.push("", "## Bill of materials", "");
  for (const row of ctx.bom) L.push(`- ${row.qty}× ${row.value ?? row.part ?? row.type}${row.footprint ? ` (${row.footprint})` : ""} — ${row.refs.join(", ")}`);

  L.push("", "---", "*Generated by Electrace from declared values and deterministic checks.*");
  return L.join("\n");
}
